var current = "guest"

func Current() string { return current }
func Set(s string)    { current = s }

// mode_test.go
func TestDefault(t *testing.T) {
	if got := Current(); got != "guest" {
		t.Errorf("Current() = %q, want guest", got)
	}
}

func TestSetAdmin(t *testing.T) {
	Set("admin")
	if Current() != "admin" {
		t.Errorf("Current() = %q, want admin", Current())
	}
}

