func TestUpper(t *testing.T) {
	tests := []struct {
		name, in, want string
	}{
		{"lower", "go", "XX"},
		{"mixed", "Go", "YY"},
		{"upper", "GO", "GO"},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			t.Parallel()
			if got := Upper(tc.in); got != tc.want {
				t.Errorf("Upper(%q) = %q, want %q", tc.in, got, tc.want)
			}
		})
	}
}
